/**
 * hst-02 — a NUL-laden file, above the binary threshold.
 *
 * architecture §10.3 draws the line at **more than 10 % NUL in the first 4 KiB** and
 * calls such a file binary: the reader reports `E_BINARY_INPUT` (fatal) and never
 * attempts to decode it. These bytes are a plausible header and entity name followed
 * by NUL padding, so the binary verdict comes from the density and nothing else.
 *
 * First 4 KiB: 1024 NUL bytes out of 4096 (ratio 0.25).
 */

export const ID = 'hst-02';
export const FILE = 'hst-02-binary.ts';
export const HEX =
  '';

/** Exact bytes of the fixture. */
export const BYTES: Uint8Array = Uint8Array.from(Buffer.from(HEX, 'hex'));
